mapper.insert:
INSERT INTO knowledge_chat (
  user_id, title, version, created_at, updated_at
) VALUES (
  #{userId}, #{title}, #{version}, #{createdAt}, #{updatedAt}
)

mapper.select:
SELECT 
FROM knowledge_chat
WHERE chat_id = #{chatId}
  AND user_id = #{userId}
  AND deleted_at IS NULL

SELECT 
FROM knowledge_chat
WHERE user_id = #{userId}
  AND deleted_at IS NULL
ORDER BY updated_at DESC, chat_id DESC
LIMIT #{limit}

mapper.update:
UPDATE knowledge_chat
SET title = #{title}
WHERE chat_id = #{chatId}
  AND user_id = #{userId}
  AND deleted_at IS NULL

UPDATE knowledge_chat
SET deleted_at = #{deletedAt},
    version = version + 1
WHERE chat_id = #{chatId}
  AND user_id = #{userId}
  AND deleted_at IS NULL

UPDATE knowledge_chat
SET version = version + 1,
    updated_at = #{updatedAt},
    memory_summary = CAST(#{memory.memorySummary} AS JSONB),
    summary_through_message_id = #{memory.summaryThroughMessageId}
WHERE chat_id = #{chatId}
  AND user_id = #{userId}
  AND version = #{version}
  AND deleted_at IS NULL
